import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const pkgPath = fileURLToPath(new URL("../package.json", import.meta.url));

if (process.argv[2] !== "version") {
  process.stderr.write("Usage: node src/cli.js version\n");
  process.exitCode = 1;
} else {
  const pkg = JSON.parse(readFileSync(pkgPath, "utf8"));
  if (typeof pkg.version !== "string" || pkg.version === "") {
    process.stderr.write("Error: package.json has no version field\n");
    process.exitCode = 1;
  } else {
    console.log(pkg.version);
  }
}

import test from "node:test";
import assert from "node:assert/strict";
import { execFileSync, spawnSync } from "node:child_process";
import { copyFileSync, mkdirSync, mkdtempSync, readFileSync, rmdirSync, unlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const cli = fileURLToPath(new URL("../src/cli.js", import.meta.url));
const pkg = JSON.parse(readFileSync(fileURLToPath(new URL("../package.json", import.meta.url)), "utf8"));

test("version prints package.json version", () => {
  const out = execFileSync(process.execPath, [cli, "version"], { encoding: "utf8" });
  assert.equal(out, `${pkg.version}\n`);
});

test("version ignores extra arguments", () => {
  const out = execFileSync(process.execPath, [cli, "version", "extra"], { encoding: "utf8" });
  assert.equal(out, `${pkg.version}\n`);
});

test("unknown or missing command exits 1 with usage", () => {
  for (const args of [[cli], [cli, "bogus"]]) {
    const res = spawnSync(process.execPath, args, { encoding: "utf8" });
    assert.equal(res.status, 1);
    assert.equal(res.stdout, "");
    assert.match(res.stderr, /Usage: node src\/cli\.js version/);
  }
});

test("version exits 1 when package.json has no version field", () => {
  const dir = mkdtempSync(join(tmpdir(), "cli-noversion-"));
  const srcDir = join(dir, "src");
  const copied = join(srcDir, "cli.js");
  const pkgFile = join(dir, "package.json");
  mkdirSync(srcDir);
  copyFileSync(cli, copied);
  writeFileSync(pkgFile, '{"type":"module"}');
  try {
    const res = spawnSync(process.execPath, [copied, "version"], { encoding: "utf8" });
    assert.equal(res.status, 1);
    assert.equal(res.stdout, "");
    assert.match(res.stderr, /Error: package\.json has no version field/);
  } finally {
    unlinkSync(copied);
    unlinkSync(pkgFile);
    rmdirSync(srcDir);
    rmdirSync(dir);
  }
});
